// n8n Code node — "Build Celebration Emails" (Run Once for All Items)
// Turns the HRIS "pay cycle closed" event into ONE item per recipient, each
// carrying a ready-to-send email plus the three close-out files as binaries.
//
// Fired by the HRIS close-out route (POST /api/payment-dispatches/cycle-closeout)
// the moment a FRESH close-out record is filed — that is the ONLY trigger since
// 2026-09-04 (the 100%-strip trigger was removed after two false firings). The
// HRIS claims a per-cycle marker before calling, so one week never lands here
// twice; a reopened-then-re-closed week arrives with celebrate:false and gets a
// plain "close-out files" email instead of confetti.
//
// Payload (n8n may nest the POST body under `.body`):
//   {
//     event: 'payment_cycle.completed', trigger: 'cycle_closed', celebrate: true|false,
//     cycle: { source_file, cycle_id, label, period_start, period_end, completed_at, completed_by },
//     stats: { paid_count, total_count, unpaid_count, total_paid_usd, total_paid_php },
//     recipients: [ { email, name } ],
//     attachments: [ { filename, content_type, bytes, content_base64 } ],   // CSV, XLSX, PDF
//     attachments_error: string|null,   // set when the HRIS could not build/attach the files
//     test: true                        // Admin → Webhooks test run (goes to the admin only)
//   }
//
// HONESTY RULE: the wording follows stats.unpaid_count. "100% PAID" appears ONLY
// when unpaid_count is 0. A closed week that still owes people says so.

// --- OPTIONAL shared-secret gate ---
// Leave '' to accept any caller. To lock down: put a long random string here AND
// set HRIS env N8N_PAYMENT_CYCLE_COMPLETE_SECRET to the same value (sent as the
// 'x-webhook-secret' header).
const REQUIRED_SECRET = '';

const LOGO = 'https://simple-hris.vercel.app/simple-logo.png';
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const MAX = 300;

const root = (items[0] && items[0].json) || {};
const body = (root && typeof root.body === 'object' && root.body) ? root.body : root;
const headers = (root && typeof root.headers === 'object' && root.headers) ? root.headers : {};

const providedSecret = headers['x-webhook-secret'] || headers['X-Webhook-Secret'] || body.secret || '';
if (REQUIRED_SECRET && providedSecret !== REQUIRED_SECRET) {
  throw new Error('Unauthorized: missing or invalid webhook secret.');
}

function esc(v) {
  if (v == null) return '';
  return String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
function firstName(name) {
  const n = (name == null ? '' : String(name)).trim();
  return n ? n.split(/\s+/)[0] : '';
}
function num(v) {
  if (v == null || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}
function fmtInt(n) { return n.toLocaleString('en-US', { maximumFractionDigits: 0 }); }
function fmtMoney(n) { return n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
const MONTHS = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
function fmtDay(iso) {
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(iso == null ? '' : iso));
  if (!m) return '';
  const mi = Number(m[2]) - 1;
  if (mi < 0 || mi > 11) return '';
  return MONTHS[mi] + ' ' + Number(m[3]);
}

// --- cycle facts ---
const cycle = (body.cycle && typeof body.cycle === 'object') ? body.cycle : {};
const stats = (body.stats && typeof body.stats === 'object') ? body.stats : {};
const isTest = body.test === true;
const celebrate = body.celebrate !== false;

const label = String(cycle.label || body.label || '').trim();
const periodStart = fmtDay(cycle.period_start || body.period_start);
const periodEnd = fmtDay(cycle.period_end || body.period_end);
const periodLine = (periodStart && periodEnd) ? (periodStart + ' – ' + periodEnd) : '';
const cycleName = label || (periodLine ? (periodLine + ' payroll') : "this week's payroll");

const paidCount = num(stats.paid_count);
const totalCount = num(stats.total_count);
const unpaidCount = num(stats.unpaid_count) || 0;
const totalUsd = num(stats.total_paid_usd);
const totalPhp = num(stats.total_paid_php);
const completedBy = String(cycle.completed_by || '').trim();
const fullyPaid = unpaidCount === 0;

let completedAt = '';
const completedAtRaw = cycle.completed_at || '';
if (completedAtRaw) {
  const d = new Date(completedAtRaw);
  if (!isNaN(d.getTime())) {
    try {
      completedAt = d.toLocaleString('en-US', { timeZone: 'Asia/Manila', month: 'short', day: 'numeric', year: 'numeric', hour: 'numeric', minute: '2-digit' }) + ' PH time';
    } catch (e) { completedAt = ''; }
  }
}

// --- recipients ---
const collected = [];
if (Array.isArray(body.recipients)) {
  for (const r of body.recipients) {
    if (!r) continue;
    collected.push({ email: r.email || r.work_email || r.to, name: r.name || '' });
  }
}
const seen = new Map();
for (const c of collected) {
  const email = (c.email == null ? '' : String(c.email)).trim().toLowerCase();
  if (!email || !EMAIL_RE.test(email)) continue;
  const name = (c.name == null ? '' : String(c.name)).trim();
  if (!seen.has(email)) seen.set(email, name);
  else if (!seen.get(email) && name) seen.set(email, name);
}
if (seen.size === 0) {
  throw new Error('No valid recipient email(s) in payload — expected recipients: [{ email, name }]. Note: the Admin -> Webhooks Test button sends none, so a failing Test still proves the URL reaches this workflow; use "Send test run" in Open automation instead.');
}
if (seen.size > MAX) {
  throw new Error('Too many recipients (' + seen.size + '; max ' + MAX + ').');
}

// --- attachments → binaries (same files for every recipient) ---
const rawAttachments = Array.isArray(body.attachments) ? body.attachments : [];
const binary = {};
const attachedNames = [];
let idx = 0;
for (const a of rawAttachments) {
  if (!a || typeof a.content_base64 !== 'string' || !a.content_base64 || a.content_base64 === '…') continue;
  const filename = String(a.filename || ('attachment-' + idx));
  const mime = String(a.content_type || 'application/octet-stream').split(';')[0].trim();
  try {
    binary['file' + idx] = await this.helpers.prepareBinaryData(Buffer.from(a.content_base64, 'base64'), filename, mime);
    attachedNames.push(filename);
    idx++;
  } catch (e) {
    // A bad file must not stop the email — say so in the body instead.
  }
}
const attachmentsError = body.attachments_error ? String(body.attachments_error) : (rawAttachments.length && !attachedNames.length ? 'The close-out files could not be attached.' : '');

// --- festive bits (inline-block only — Gmail-safe) ---
const CONFETTI = ['#f97316', '#fbbf24', '#34d399', '#38bdf8', '#a78bfa', '#fb7185'];
function garland(count, seedOffset) {
  let out = '<div aria-hidden="true" style="line-height:1;font-size:0">';
  for (let i = 0; i < count; i++) {
    const color = CONFETTI[(i + seedOffset) % CONFETTI.length];
    const tall = (i + seedOffset) % 3 === 0;
    const w = tall ? 5 : 8, h = tall ? 12 : 8;
    const radius = tall ? '2px' : '50%';
    const rot = ((i * 37 + seedOffset * 53) % 56) - 28;
    const delay = ((i * 13 + seedOffset * 7) % 22) / 10;
    out += '<span class="hris-cf" style="display:inline-block;width:' + w + 'px;height:' + h + 'px;margin:0 5px;background:' + color + ';border-radius:' + radius + ';transform:rotate(' + rot + 'deg);animation-delay:' + delay + 's"></span>';
  }
  return out + '</div>';
}
function balloons() {
  return '<div aria-hidden="true" style="line-height:1;margin:14px 0 12px">' +
    '<span class="hris-b hris-b1" style="display:inline-block;font-size:30px;margin:0 6px">🎈</span>' +
    '<span class="hris-b hris-b2" style="display:inline-block;font-size:24px;margin:0 4px">🎊</span>' +
    '<span class="hris-b hris-b3" style="display:inline-block;font-size:38px;margin:0 8px">🎈</span>' +
    '<span class="hris-b hris-b4" style="display:inline-block;font-size:24px;margin:0 4px">🎉</span>' +
    '<span class="hris-b hris-b5" style="display:inline-block;font-size:30px;margin:0 6px">🎈</span>' +
    '</div>';
}

const tiles = [];
if (paidCount != null && paidCount > 0) tiles.push({ big: fmtInt(paidCount), small: paidCount === 1 ? 'payment sent' : 'payments sent' });
if (unpaidCount > 0) tiles.push({ big: fmtInt(unpaidCount), small: unpaidCount === 1 ? 'still owed' : 'still owed' });
if (totalUsd != null && totalUsd > 0) tiles.push({ big: '$' + fmtMoney(totalUsd), small: 'dispatched (USD)' });
if (totalPhp != null && totalPhp > 0) tiles.push({ big: '&#8369;' + fmtMoney(totalPhp), small: 'dispatched (PHP)' });
function tilesRow() {
  if (tiles.length === 0) return '';
  let cells = '';
  for (let i = 0; i < tiles.length; i++) {
    if (i > 0) cells += '<td style="width:10px;font-size:0;line-height:0">&nbsp;</td>';
    cells += '<td align="center" width="' + Math.floor(100 / tiles.length) + '%" style="background:#fff7ed;border:1px solid #fed7aa;border-radius:12px;padding:14px 8px">' +
      '<div style="font-size:20px;font-weight:bold;color:#c2410c;line-height:1.2">' + tiles[i].big + '</div>' +
      '<div style="margin-top:3px;font-size:11px;letter-spacing:.4px;text-transform:uppercase;color:#9a3412">' + tiles[i].small + '</div></td>';
  }
  return '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:6px 0 16px"><tr>' + cells + '</tr></table>';
}

const wrapBits = [];
if (completedAt) wrapBits.push('Cycle closed ' + esc(completedAt));
if (completedBy) wrapBits.push('by ' + esc(completedBy));

function filesBlock() {
  let inner = '';
  if (attachedNames.length) {
    inner += '<div style="font-size:13px;font-weight:bold;color:#18181b">&#128206; Close-out files attached</div><ul style="margin:6px 0 0;padding-left:18px;font-size:12px;line-height:1.7;color:#3f3f46">';
    for (const n of attachedNames) inner += '<li>' + esc(n) + '</li>';
    inner += '</ul>';
  }
  if (attachmentsError) {
    inner += '<div style="margin-top:' + (attachedNames.length ? '8px' : '0') + ';font-size:12px;line-height:1.6;color:#9a3412">' + esc(attachmentsError) + ' The record itself is filed — download the files from Payment Dispatch.</div>';
  }
  if (!inner) return '';
  return '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 18px"><tr><td style="background:#f4f4f5;border:1px solid #e4e4e7;border-radius:12px;padding:14px 16px">' + inner + '</td></tr></table>';
}

// Headline + copy follow the FACTS.
const headBadge = celebrate ? (fullyPaid ? '&#127881; Payment cycle complete' : '&#128274; Pay cycle closed') : '&#128206; Close-out files';
const headBig = celebrate
  ? (fullyPaid ? '100% <span style="color:#4ade80">PAID</span>' : 'CYCLE <span style="color:#fbbf24">CLOSED</span>')
  : 'CLOSE-OUT <span style="color:#d4d4d8">FILES</span>';
const headSub = celebrate
  ? ((label || periodLine ? esc(label || periodLine) + ' &middot; ' : '') + (fullyPaid ? 'every single payment sent' : fmtInt(paidCount || 0) + ' paid &middot; ' + fmtInt(unpaidCount) + ' still owed'))
  : (esc(label || periodLine) + ' &middot; re-closed; files for the new record');

function leadParagraph() {
  if (!celebrate) {
    return '<p style="margin:0 0 16px;font-size:14px;line-height:1.65;color:#3f3f46">The pay cycle <strong>' + esc(cycleName) + '</strong> was closed again after a reopen. The updated close-out files are attached; this week already had its celebration, so this is just the paperwork.</p>';
  }
  if (fullyPaid) {
    return '<p style="margin:0 0 16px;font-size:14px;line-height:1.65;color:#3f3f46">Confetti cannons, please 🎊 — <strong>every payment in ' + esc(cycleName) + ' has been dispatched and the cycle is closed.</strong> Nothing pending, nothing blocked: a fully successful payment cycle.</p>';
  }
  return '<p style="margin:0 0 16px;font-size:14px;line-height:1.65;color:#3f3f46"><strong>' + esc(cycleName) + ' is closed.</strong> ' + fmtInt(paidCount || 0) + ' payments went out through the HRIS; <strong>' + fmtInt(unpaidCount) + (unpaidCount === 1 ? ' payable person was' : ' payable people were') + ' still owed at close</strong> — they are listed by name in the attached close-out. Great work getting the week over the line.</p>';
}

function renderHtml(name) {
  const fn = esc(firstName(name));
  const greeting = fn ? ('Hi ' + fn + ',') : 'Hi team,';
  const preheader = celebrate
    ? (fullyPaid ? '100% paid — every payment in ' + esc(cycleName) + ' has been dispatched. Take a bow, team 🎉' : esc(cycleName) + ' is closed — ' + fmtInt(paidCount || 0) + ' paid, ' + fmtInt(unpaidCount) + ' still owed. Files attached.')
    : 'Updated close-out files for ' + esc(cycleName) + '.';
  return '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' + (celebrate ? 'Pay cycle closed' : 'Close-out files') + '</title>' +
    '<style>' +
      '.hris-b{animation:hrisFloat 3.4s ease-in-out infinite;transform-origin:50% 100%}' +
      '.hris-b2{animation-duration:4.2s;animation-delay:.4s}.hris-b3{animation-duration:3.7s;animation-delay:.8s}.hris-b4{animation-duration:4.5s;animation-delay:.2s}.hris-b5{animation-duration:3.9s;animation-delay:1.1s}' +
      '.hris-cf{animation:hrisDrift 2.8s ease-in-out infinite alternate}' +
      '@keyframes hrisFloat{0%,100%{transform:translateY(0) rotate(-4deg)}50%{transform:translateY(-9px) rotate(5deg)}}' +
      '@keyframes hrisDrift{0%{transform:translateY(-5px) rotate(-16deg)}100%{transform:translateY(7px) rotate(18deg)}}' +
      '@media (prefers-reduced-motion:reduce){.hris-b,.hris-cf{animation:none!important}}' +
    '</style></head>' +
    '<body style="margin:0;background:#f4f4f5;padding:24px 12px;font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#18181b">' +
      '<div style="display:none;max-height:0;overflow:hidden;opacity:0;color:transparent;font-size:1px;line-height:1px">' + preheader + '</div>' +
      '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f4f5"><tr><td align="center">' +
        '<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="width:100%;max-width:600px;background:#ffffff;border:1px solid #e4e4e7;border-radius:16px;overflow:hidden;box-shadow:0 8px 28px rgba(249,115,22,0.12)">' +
          '<tr><td style="padding:18px 28px 12px"><img src="' + LOGO + '" alt="Simple" width="88" height="30" style="display:block;border:0;height:30px;width:88px"></td></tr>' +
          '<tr><td align="center" bgcolor="#0a0a0b" style="background:#0a0a0b;padding:26px 24px 28px;border-bottom:4px solid #f97316">' +
            (celebrate ? garland(14, 0) + balloons() : '') +
            '<span style="display:inline-block;background:#f97316;color:#ffffff;font-size:11px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;padding:6px 14px;border-radius:999px">' + headBadge + '</span>' +
            '<div style="margin-top:14px;font-size:44px;line-height:1.1;color:#ffffff;font-weight:800">' + headBig + '</div>' +
            '<div style="margin-top:8px;font-size:14px;color:#d4d4d8">' + headSub + '</div>' +
            (celebrate ? '<div style="margin-top:18px">' + garland(14, 3) + '</div>' : '') +
          '</td></tr>' +
          '<tr><td style="padding:24px 28px 6px">' +
            (isTest ? '<p style="margin:0 0 12px;padding:8px 12px;background:#fef3c7;border:1px solid #fcd34d;border-radius:8px;font-size:12px;color:#92400e"><strong>TEST RUN</strong> from Admin &rarr; Webhooks. Fictional week, sent to you only.</p>' : '') +
            '<p style="margin:0 0 12px;font-size:15px;color:#18181b">' + greeting + '</p>' +
            leadParagraph() +
            tilesRow() +
            filesBlock() +
            (wrapBits.length ? '<p style="margin:0 0 16px;font-size:12px;color:#71717a">' + wrapBits.join(' ') + '</p>' : '') +
            (celebrate ? '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 18px"><tr><td style="background-color:#fff7ed;background-image:linear-gradient(135deg,#fff7ed,#ffedd5);border:1px solid #fed7aa;border-radius:12px;padding:16px 18px">' +
              '<div style="font-size:14px;font-weight:bold;color:#9a3412">Take a bow, Accounting team 🥳</div>' +
              '<div style="margin-top:6px;font-size:13px;line-height:1.65;color:#7c2d12">Behind every on-time salary is your checking, chasing and double-checking. Payday doesn&rsquo;t happen by itself — it happens because of you. Thank you for the hard work; this cycle is officially in the books.</div>' +
            '</td></tr></table>' : '') +
            (celebrate ? '<p style="margin:0 0 8px;font-size:14px;line-height:1.6;color:#3f3f46">Enjoy the moment — you earned it. 🎈🎈🎈</p>' : '') +
          '</td></tr>' +
          '<tr><td style="padding:16px 28px 20px;border-top:1px solid #f4f4f5"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td style="font-size:12px;color:#52525b;font-weight:bold">Simple &middot; Payroll</td><td align="right" style="font-size:11px;color:#71717a">Automated from Simple HRIS &middot; Payment Dispatch &middot; pay cycle closed</td></tr></table></td></tr>' +
        '</table>' +
        '<div style="max-width:600px;margin:12px auto 0;font-size:11px;color:#71717a;text-align:center;line-height:1.5">You are receiving this because you are on the Accounting celebration list in Simple HRIS (Admin &rarr; Webhooks &rarr; Open automation).</div>' +
      '</td></tr></table>' +
    '</body></html>';
}

const SUBJECT = (isTest ? '[TEST RUN] ' : '') + (celebrate
  ? (fullyPaid ? '🎉 100% paid — ' + cycleName + ' cycle is closed!' : '🔒 ' + cycleName + ' is closed — ' + fmtInt(paidCount || 0) + ' paid, ' + fmtInt(unpaidCount) + ' still owed')
  : '📎 Close-out files — ' + cycleName);

const out = [];
for (const [email, name] of seen) {
  const item = { json: { to: email, name: name || '', subject: SUBJECT, html: renderHtml(name), attached: attachedNames.length } };
  if (attachedNames.length) item.binary = binary;
  out.push(item);
}
return out;
